From 3b20fb9653b005c045bcbdc518e87f37dd02bc6f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:47:28 +0100
Subject: [PATCH] AppletPopup: keep the opposite edge in place while the user
 resizes

KWin ignores popup positions during a resize, but the popup was still
put back around its applet, so it drew borders for the wrong place and
by a screen edge reset its size. It now follows where KWin keeps it.

BUG: 504018
---
 src/plasmaquick/appletpopup.cpp         |  5 ++++
 src/plasmaquick/popupplasmawindow.cpp   | 34 ++++++++++++++++++++++++-
 src/plasmaquick/popupplasmawindow.h     |  8 ++++++
 src/plasmaquick/windowresizehandler.cpp |  1 +
 src/plasmaquick/windowresizehandler.h   |  3 +++
 5 files changed, 50 insertions(+), 1 deletion(-)

diff --git a/src/plasmaquick/appletpopup.cpp b/src/plasmaquick/appletpopup.cpp
index edb9c6885..668eed01f 100644
--- a/src/plasmaquick/appletpopup.cpp
+++ b/src/plasmaquick/appletpopup.cpp
@@ -84,6 +84,11 @@ AppletPopup::AppletPopup()
     updateWindowResizerEdges();
     connect(this, &PopupPlasmaWindow::nearbyBordersChanged, this, updateWindowResizerEdges);
     connect(this, &PopupPlasmaWindow::effectivePopupDirectionChanged, this, updateWindowResizerEdges);
+    connect(windowResizer, &WindowResizeHandler::resizeStarted, this, [this](Qt::Edges edges) {
+        // keep the size the user picks, like when it's read from the config
+        m_sizeExplicitlySetFromConfig = true;
+        setResizeEdges(edges);
+    });

     connect(this, &PlasmaWindow::mainItemChanged, this, &AppletPopup::onMainItemChanged);
     connect(this, &PlasmaWindow::paddingChanged, this, &AppletPopup::updateMaxSize);
diff --git a/src/plasmaquick/popupplasmawindow.cpp b/src/plasmaquick/popupplasmawindow.cpp
index 3230442c9..c344b0a5c 100644
--- a/src/plasmaquick/popupplasmawindow.cpp
+++ b/src/plasmaquick/popupplasmawindow.cpp
@@ -32,6 +32,7 @@ public:
     void updateSlideEffect(const QRect &globalPosition);
     void updatePosition();
     void updatePosition(const QPoint &position);
+    void updatePositionAfterResize(const QSize &oldSize);
     void updateBorders(const QRect &globalPosition);
     void updateVisualParentWindow();

@@ -49,6 +50,7 @@ public:
     Qt::Edge m_popupDirection = Qt::TopEdge;
     Qt::Edge m_effectivePopupDirection = Qt::TopEdge;
     Qt::Edges m_nearbyBorders;
+    Qt::Edges m_resizeEdges;
 };

 PopupPlasmaWindowPrivate::PopupPlasmaWindowPrivate(PopupPlasmaWindow *_q)
@@ -192,6 +194,30 @@ void PopupPlasmaWindowPrivate::updatePosition(const QPoint &position)
     PlasmaShellWaylandIntegration::get(q)->setPosition(position);
 }

+void PopupPlasmaWindowPrivate::updatePositionAfterResize(const QSize &oldSize)
+{
+    if (!m_resizeEdges) {
+        updatePosition();
+        return;
+    }
+
+    // The compositor doesn't move the popup while the user resizes it, it keeps
+    // the edges opposite to the dragged ones in place, so follow it
+    QRect globalPosition = q->geometry();
+    if (m_resizeEdges & Qt::LeftEdge) {
+        globalPosition.moveRight(q->x() + oldSize.width() - 1);
+    }
+    if (m_resizeEdges & Qt::TopEdge) {
+        globalPosition.moveBottom(q->y() + oldSize.height() - 1);
+    }
+
+    if (KWindowSystem::isPlatformWayland()) {
+        updatePosition(globalPosition.topLeft());
+    }
+
+    updateBorders(globalPosition);
+}
+
 void PopupPlasmaWindowPrivate::updateBorders(const QRect &globalPosition)
 {
     // disables borders for the edges that are touching the screen edge
@@ -462,13 +488,14 @@ bool PopupPlasmaWindow::event(QEvent *event)
         }
         break;
     case QEvent::Show:
+        d->m_resizeEdges = {};
         d->updatePosition();
         break;
     case QEvent::Resize:
     {
         auto resizeEvent = static_cast<QResizeEvent*>(event);
         if (resizeEvent->oldSize() != resizeEvent->size()) {
-            d->updatePosition();
+            d->updatePositionAfterResize(resizeEvent->oldSize());
         }
         break;
     }
@@ -478,6 +505,11 @@ bool PopupPlasmaWindow::event(QEvent *event)
     return PlasmaQuick::PlasmaWindow::event(event);
 }

+void PopupPlasmaWindow::setResizeEdges(Qt::Edges edges)
+{
+    d->m_resizeEdges = edges;
+}
+
 void PopupPlasmaWindow::queuePositionUpdate()
 {
     d->m_needsReposition = true;
diff --git a/src/plasmaquick/popupplasmawindow.h b/src/plasmaquick/popupplasmawindow.h
index 9d66ef66a..d9c8865d6 100644
--- a/src/plasmaquick/popupplasmawindow.h
+++ b/src/plasmaquick/popupplasmawindow.h
@@ -149,6 +149,14 @@ Q_SIGNALS:
     void marginChanged();
     void nearbyBordersChanged();

+protected:
+    /*!
+     * Tells the popup that the user started resizing it from \a edges. Until it is
+     * shown again, the opposite edges then stay where they are, like the compositor
+     * keeps them, instead of the popup being placed again around its visual parent.
+     */
+    void setResizeEdges(Qt::Edges edges);
+
 protected Q_SLOTS:
     void queuePositionUpdate();

diff --git a/src/plasmaquick/windowresizehandler.cpp b/src/plasmaquick/windowresizehandler.cpp
index 620337614..d244ea24a 100644
--- a/src/plasmaquick/windowresizehandler.cpp
+++ b/src/plasmaquick/windowresizehandler.cpp
@@ -88,6 +88,7 @@ bool WindowResizeHandler::eventFilter(QObject *watched, QEvent *event)
             const QPointF globalMousePos = me->globalPosition();
             const Qt::Edges sides = d->hitTest(globalMousePos) & d->activeEdges;
             if (sides) {
+                Q_EMIT resizeStarted(sides);
                 d->window->startSystemResize(sides);
                 return true;
             }
diff --git a/src/plasmaquick/windowresizehandler.h b/src/plasmaquick/windowresizehandler.h
index ecd2f217b..c3541d202 100644
--- a/src/plasmaquick/windowresizehandler.h
+++ b/src/plasmaquick/windowresizehandler.h
@@ -33,6 +33,9 @@ public:

     bool eventFilter(QObject *watched, QEvent *event) override;

+Q_SIGNALS:
+    void resizeStarted(Qt::Edges edges);
+
 private:
     std::unique_ptr<WindowResizeHandlerPrivate> d;
 };
